-- Owner request (2026-09-14): 20 synthetic community posts per open city across the post
-- categories, authored by distinct seed profiles, dated across early September so the feeds
-- look lived-in before the Edmonton launch build. Then give seed profiles a random trust badge (1-3).

insert into public.posts (id, author_id, city_id, tag_id, title, body, hashtags, created_at)
select seed.id, seed.author_id, seed.city_id, tag.id, seed.title, seed.body, seed.hashtags, seed.created_at
from (values
  ('20000000-0000-0000-0000-000000000056'::uuid, '10000000-0000-0000-0000-000000000046'::uuid, 'vancouver', 'life', E'비 오는 날 스탠리파크 한 바퀴, 오히려 좋았어요', E'비 예보 보고 포기하려다 그냥 나갔는데 사람도 없고 바다 냄새도 진해서 좋더라고요. 방수 자켓만 있으면 밴쿠버 비는 산책 방해가 안 되는 것 같아요. 다들 비 오는 날 어디 걸으세요?', array[E'스탠리파크', E'산책', E'밴쿠버비'], '2026-09-03 10:00:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000057'::uuid, '10000000-0000-0000-0000-000000000051'::uuid, 'vancouver', 'life', E'다운타운에서 조용히 공부할 카페 찾는 중', E'노트북 펴고 두세 시간 앉아 있어도 눈치 안 보이는 카페 아시는 분 있나요? 콘센트 있고 와이파이 되는 곳이면 더 좋고요. 저는 요즘 웨스트엔드 쪽 한 곳 단골인데 주말엔 자리가 없어요.', array[E'카페', E'다운타운', E'공부'], '2026-09-10 12:03:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000058'::uuid, '10000000-0000-0000-0000-000000000053'::uuid, 'vancouver', 'life', E'첫 가을, 단풍은 어디가 제일 예뻐요?', E'작년엔 못 봤는데 올해는 단풍 제대로 보고 싶어요. 퀸엘리자베스 공원이 좋다는 얘기 들었는데 차 없이 갈 수 있는 곳 추천 부탁해요.', array[E'가을', E'단풍', E'주말나들이'], '2026-09-07 21:06:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000059'::uuid, '10000000-0000-0000-0000-000000000067'::uuid, 'vancouver', 'life', E'랭리 파머스마켓 다녀왔어요', E'토요일 아침에 갔는데 복숭아랑 옥수수가 진짜 달았어요. 시내보다 훨씬 싸고 양도 많아서 차 있으신 분들은 한 번 가보셔도 좋을 것 같아요. 현금 챙겨가세요.', array[E'파머스마켓', E'랭리', E'주말'], '2026-09-01 17:58:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000060'::uuid, '10000000-0000-0000-0000-000000000040'::uuid, 'vancouver', 'food', E'리치몬드 딤섬 세 군데 비교해봤어요', E'주말마다 한 곳씩 갔는데 가격은 비슷하고 대기 시간이 제일 큰 차이였어요. 11시 전에 가면 어디든 바로 앉을 수 있더라고요. 하가우는 셋 다 맛있었고 창펀은 호불호가 갈릴 듯해요.', array[E'딤섬', E'리치몬드', E'맛집탐방'], '2026-09-10 19:23:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000061'::uuid, '10000000-0000-0000-0000-000000000047'::uuid, 'vancouver', 'food', E'써리에서 감자탕 먹을 만한 곳', E'한국 맛 나는 감자탕 집 찾고 있어요. 뼈에 살이 좀 붙어 있는 곳이면 좋겠어요. 써리나 코퀴틀람 쪽으로요.', array[E'감자탕', E'써리', E'한식'], '2026-09-10 12:29:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000062'::uuid, '10000000-0000-0000-0000-000000000048'::uuid, 'vancouver', 'food', E'메트로타운 점심 만원 이하로 해결하기', E'환율 생각하면 점심값이 무섭잖아요. 메트로타운 근처 직장인분들 만원 이하로 배부르게 먹는 곳 있으면 공유해요. 저는 푸드코트 베트남 국수 자주 갑니다.', array[E'점심', E'메트로타운', E'가성비'], '2026-09-08 11:21:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000063'::uuid, '10000000-0000-0000-0000-000000000038'::uuid, 'vancouver', 'settlement', E'SIN 넘버 발급, 예약 없이 가도 되나요', E'서비스캐나다 사무실 예약 없이 가도 되는지 궁금해요. 다운타운 쪽으로 갈 예정인데 대기 시간이 어느 정도였는지 최근 경험 있으신 분 알려주세요.', array[E'SIN', E'정착초기', E'서비스캐나다'], '2026-09-05 11:41:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000064'::uuid, '10000000-0000-0000-0000-000000000063'::uuid, 'vancouver', 'settlement', E'BC 운전면허 교환 후기 (한국 면허)', E'한국 면허랑 번역 공증본 들고 ICBC 갔더니 필기 없이 바로 교환됐어요. 필요한 서류는 여권, 면허증, 번역본, 거주지 증명 두 개였고 사진은 현장에서 찍었어요. 30분 정도 걸렸습니다.', array[E'운전면허', E'ICBC', E'정착'], '2026-09-11 16:42:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000065'::uuid, '10000000-0000-0000-0000-000000000065'::uuid, 'vancouver', 'settlement', E'핸드폰 요금제 어디 쓰세요', E'지금 월 50불 정도 내는데 데이터 20GB예요. 더 싼 데가 있다고 들었는데 통화 품질이 괜찬은 곳인지 궁금해요. 밴쿠버 시내에서 잘 터지는 통신사 기준으로요.', array[E'통신사', E'요금제', E'정착'], '2026-09-04 15:01:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000066'::uuid, '10000000-0000-0000-0000-000000000060'::uuid, 'vancouver', 'travel', E'휘슬러 당일치기 가능한가요', E'차 없이 버스로 휘슬러 당일치기 다녀오신 분 있나요? 아침 일찍 출발해서 곤돌라 타고 저녁에 돌아오는 일정 생각 중이에요.', array[E'휘슬러', E'당일치기', E'여행'], '2026-09-03 08:38:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000067'::uuid, '10000000-0000-0000-0000-000000000041'::uuid, 'vancouver', 'travel', E'빅토리아 페리 타고 1박 다녀온 후기', E'츠와센에서 페리 타고 갔는데 바다 보면서 가는 게 여행의 반이었어요. 이너하버 근처에서 하루 자고 부차드 가든 보고 왔습니다. 페리 예약은 미리 하는 게 마음 편해요.', array[E'빅토리아', E'페리', E'1박2일'], '2026-09-05 21:30:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000068'::uuid, '10000000-0000-0000-0000-000000000062'::uuid, 'vancouver', 'shopping', E'코스트코 밴쿠버 지점별 붐비는 시간', E'다운타운 지점은 평일 저녁이 제일 붐비고 버나비 지점은 주말 오전이 붐비는 느낌이에요. 여러분 경험은 어떤가요? 한적한 시간 찾아서 공유해봐요.', array[E'코스트코', E'장보기', E'생활팁'], '2026-09-02 10:39:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000069'::uuid, '10000000-0000-0000-0000-000000000056'::uuid, 'vancouver', 'shopping', E'한국 식재료 어디서 사세요', E'H마트, 한남, T&T 중에 뭘 주로 가시는지 궁금해요. 저는 김치는 한남, 과일은 T&T 이렇게 나눠서 가는데 한 번에 해결되는 곳이 있으면 좋겘어요.', array[E'한국마트', E'장보기', E'식재료'], '2026-09-04 20:04:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000070'::uuid, '10000000-0000-0000-0000-000000000055'::uuid, 'vancouver', 'transport', E'컴패스카드 월정액 vs 그때그때 충전', E'출퇴근 주 5일이면 월정액이 이득인 건 아는데, 재택이 섞이면 애매하더라고요. 여러분은 어떻게 계산하세요? 존 2개 넘나드는 기준이에요.', array[E'컴패스카드', E'대중교통', E'출퇴근'], '2026-09-02 09:44:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000071'::uuid, '10000000-0000-0000-0000-000000000066'::uuid, 'vancouver', 'transport', E'스카이트레인 막차 시간 헷갈려요', E'금요일 밤에 다운타운에서 놀다가 막차 놓칠까 조마조마했어요. 노선별로 막차가 다르던데 정리해둔 분 있으면 공유해주세요.', array[E'스카이트레인', E'막차', E'다운타운'], '2026-09-03 14:50:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000072'::uuid, '10000000-0000-0000-0000-000000000049'::uuid, 'vancouver', 'housing', E'버나비 1베드 렌트 시세 요즘 어때요', E'메트로타운 근처 1베드 알아보는데 2년 전보다 많이 올랐다고 하네요. 최근에 계약하신 분들 대략적인 시세 공유 가능할까요?', array[E'렌트', E'버나비', E'1베드'], '2026-09-10 10:05:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000073'::uuid, '10000000-0000-0000-0000-000000000061'::uuid, 'vancouver', 'housing', E'룸메이트 구할 때 꼭 물어보는 것', E'저는 청소 주기, 손님 초대, 요리 냄새 이 세 가지는 꼭 미리 맞춰요. 같이 살아보니 생활 소음이 제일 문제였어요. 다른 분들은 어떤 기준 있으세요?', array[E'룸메이트', E'하우스셰어', E'생활'], '2026-09-11 19:42:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000074'::uuid, '10000000-0000-0000-0000-000000000057'::uuid, 'vancouver', 'education', E'UBC 근처 영어 회화 스터디 있을까요', E'주중 저녁에 편하게 영어 말하기 연습할 모임을 찾고 있어요. 없으면 만들어볼까 생각도 하는데 관심 있으신 분 계신가요?', array[E'영어회화', E'UBC', E'스터디'], '2026-09-13 19:28:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000075'::uuid, '10000000-0000-0000-0000-000000000058'::uuid, 'vancouver', 'education', E'아이 초등학교 등록 준비 서류', E'9월 학기 등록 준비하는데 필요한 서류가 많네요. 거주지 증명, 아이 여권, 예방접종 기록 정도로 알고 있는데 더 챙길 게 있을까요?', array[E'초등학교', E'자녀교육', E'정착'], '2026-09-14 21:57:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000076'::uuid, '10000000-0000-0000-0000-000000000070'::uuid, 'toronto', 'life', E'하이파크 아침 산책 루틴 공유', E'출근 전에 하이파크 한 바퀴 걷는 게 요즘 하루의 시작이에요. 7시쯤 가면 사람이 거의 없어서 좋아요. 아침 산책 하시는 분들 어디 다니세요?', array[E'하이파크', E'아침루틴', E'산책'], '2026-09-07 18:53:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000077'::uuid, '10000000-0000-0000-0000-000000000087'::uuid, 'toronto', 'life', E'토론토 겨울 처음인데 뭐 준비해야 해요', E'첫 겨울 앞두고 걱정이 커요. 패딩은 어느 정도 두께여야 하는지, 부츠는 어디서 사는지 선배님들 조언 부탁드려요.', array[E'첫겨울', E'방한', E'토론토'], '2026-09-05 14:49:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000078'::uuid, '10000000-0000-0000-0000-000000000081'::uuid, 'toronto', 'life', E'하버프론트에서 노을 보기 좋은 자리', E'퇴근하고 하버프론트 가서 노을 보는데 사람 없는 자리가 있어요. 온타리오 호수 위로 지는 해가 바다 같아요. 다들 노을 명당 어디세요?', array[E'하버프론트', E'노을', E'퇴근길'], '2026-09-07 22:24:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000079'::uuid, '10000000-0000-0000-0000-000000000072'::uuid, 'toronto', 'life', E'켄싱턴 마켓 주말 나들이 후기', E'빈티지 옷 구경하다가 세 시간이 갔어요. 길거리 음식도 다양하고 사진 찍을 곳도 많아요. 주말에 할 거 없으면 한 번 가보세요.', array[E'켄싱턴마켓', E'주말', E'나들이'], '2026-09-03 19:33:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000080'::uuid, '10000000-0000-0000-0000-000000000090'::uuid, 'toronto', 'food', E'노스욕 순두부 맛집 추천해주세요', E'매운 순두부 좋아하는데 노스욕에서 한국 맛 나는 곳 찾고 있어요. 밑반찬 잘 나오는 곳이면 더 좋아요.', array[E'순두부', E'노스욕', E'한식'], '2026-09-01 09:20:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000081'::uuid, '10000000-0000-0000-0000-000000000069'::uuid, 'toronto', 'food', E'세인트로렌스 마켓 피미얼 베이컨 샌드위치', E'토론토 오면 꼭 먹어야 한다고 해서 갔는데 줄이 길었어요. 맛은 기대만큼이었고 양이 많아서 둘이 하나도 괜찬아요. 주말 오전 피하세요.', array[E'세인트로렌스마켓', E'샌드위치', E'맛집'], '2026-09-10 18:53:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000082'::uuid, '10000000-0000-0000-0000-000000000092'::uuid, 'toronto', 'food', E'미시사가 중식 딤섬 어디 가세요', E'토론토 시내까지 안 나가고 미시사가에서 딤섬 먹을 곳 찾고 있어요. 가족 단위로 가기 편한 곳이면 좋겠어요.', array[E'딤섬', E'미시사가', E'가족외식'], '2026-09-12 14:14:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000083'::uuid, '10000000-0000-0000-0000-000000000073'::uuid, 'toronto', 'settlement', E'온타리오 헬스카드 신청 후기', E'서비스온타리오 가서 신청했는데 필요한 서류가 세 가지였어요. 신분, 거주, 체류 자격 증명 각각 하나씩이요. 카드는 우편으로 3주 정도 걸렸습니다.', array[E'OHIP', E'헬스카드', E'정착'], '2026-09-06 13:28:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000084'::uuid, '10000000-0000-0000-0000-000000000078'::uuid, 'toronto', 'settlement', E'은행 계좌 어디서 만드셨어요', E'뉴커머 패키지가 있는 은행이 많던데 실제로 쓰기 편한 곳이 궁금해요. 수수료 면제 기간 끝나고 나서도 계속 쓰시는지도요.', array[E'은행계좌', E'뉴커머', E'정착'], '2026-09-10 11:52:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000085'::uuid, '10000000-0000-0000-0000-000000000076'::uuid, 'toronto', 'settlement', E'토론토 이사 후 주소 변경 체크리스트', E'이사하고 나서 바꿔야 할 주소가 생각보다 많았어요. 헬스카드, 운전면허, 은행, 통신사, CRA까지요. 빠뜨린 거 있으면 알려주세요.', array[E'이사', E'주소변경', E'체크리스트'], '2026-09-07 22:33:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000086'::uuid, '10000000-0000-0000-0000-000000000079'::uuid, 'toronto', 'travel', E'나이아가라 평일에 가면 확실히 한산해요', E'수요일 오후에 갔는데 주말의 반도 안 되는 인파였어요. 보트 투어도 바로 탔고요. 휴가 낼 수 있으면 평일 추천드려요.', array[E'나이아가라', E'평일여행', E'당일치기'], '2026-09-09 19:00:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000087'::uuid, '10000000-0000-0000-0000-000000000089'::uuid, 'toronto', 'travel', E'토론토 아일랜드 자전거 대여 팁', E'페리 타고 들어가서 자전거 빌렸는데 섬 한 바퀴 두 시간 정도 걸렸어요. 물이랑 간식 챙겨가세요, 섬 안은 비싸요.', array[E'토론토아일랜드', E'자전거', E'주말'], '2026-09-11 14:37:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000088'::uuid, '10000000-0000-0000-0000-000000000071'::uuid, 'toronto', 'shopping', E'요크데일 세일 시즌 언제 시작하나요', E'가을 옷 사려고 기다리는 중인데 큰 세일이 언제쯤 시작하는지 아시는 분 있나요? 작년 경험 공유해주시면 감사해요.', array[E'요크데일', E'세일', E'쇼핑'], '2026-09-01 21:54:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000089'::uuid, '10000000-0000-0000-0000-000000000095'::uuid, 'toronto', 'shopping', E'코리아타운 한국 마트 vs 노스욕 마트', E'블루어 코리아타운 쪽 마트랑 노스욕 쪽 큰 마트 가격 차이가 있나요? 저는 노스욕이 더 싼 느낌인데 교통비 생각하면 비슷한 것 같아요.', array[E'한국마트', E'코리아타운', E'노스욕'], '2026-09-11 21:58:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000090'::uuid, '10000000-0000-0000-0000-000000000097'::uuid, 'toronto', 'transport', E'TTC 월정액 프레스토 이득인가요', E'주 4일 출근이면 월정액이 이득인지 계산이 애매해요. 다들 어떻게 하세요? 고트레인 환승 할인도 같이 알려주시면 감사해요.', array[E'TTC', E'프레스토', E'출퇴근'], '2026-09-08 18:51:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000091'::uuid, '10000000-0000-0000-0000-000000000068'::uuid, 'toronto', 'transport', E'미시사가에서 다운타운 출근, 차 vs 고트레인', E'차로 가면 주차비가 무섭고 고트레인은 시간이 좀 걸려요. 비슷한 동선으로 출근하시는 분들 어떻게 하시는지 궁금해요.', array[E'고트레인', E'출근', E'미시사가'], '2026-09-10 18:03:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000092'::uuid, '10000000-0000-0000-0000-000000000080'::uuid, 'toronto', 'housing', E'노스욕 콘도 1베드 시세 공유해요', E'최근에 핀치역 근처 1베드 계약했어요. 시세는 작년보다 조금 내린 느낌이었고 주차 포함 여부가 가격 차이를 많이 만들었어요.', array[E'콘도', E'노스욕', E'렌트'], '2026-09-04 22:36:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000093'::uuid, '10000000-0000-0000-0000-000000000093'::uuid, 'toronto', 'housing', E'렌트 계약서에서 꼭 확인할 항목', E'계약 전에 유틸리티 포함 여부, 계약 종료 통보 기간, 보증금 반환 조건은 꼭 봤어요. 온타리오 표준 임대 계약서 양식인지도요.', array[E'렌트계약', E'체크리스트', E'주거'], '2026-09-04 22:14:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000094'::uuid, '10000000-0000-0000-0000-000000000084'::uuid, 'toronto', 'education', E'토론토 도서관 카드로 할 수 있는 것', E'책만 빌리는 줄 알았는데 박물관 패스, 온라인 강좌, 악기 대여까지 되더라고요. 무료라서 정착 초기에 만들어두면 좋아요.', array[E'토론토도서관', E'무료', E'정착팁'], '2026-09-01 08:05:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000095'::uuid, '10000000-0000-0000-0000-000000000074'::uuid, 'toronto', 'education', E'아이 프렌치 이머전 프로그램 고민', E'초등 입학 앞두고 프렌치 이머전을 넣을지 고민이에요. 부모가 프랑스어를 못해도 괜찬은지 경험 있으신 분 이야기 듣고 싶어요.', array[E'프렌치이머전', E'자녀교육', E'초등'], '2026-09-10 20:23:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000096'::uuid, '10000000-0000-0000-0000-000000000109'::uuid, 'edmonton', 'life', E'에드먼튼 리버밸리 산책로 처음 걸어봤어요', E'시내 바로 옆에 이렇게 큰 계곡 공원이 있다는 게 놀라웠어요. 노스사스카츄완 강 따라 걷다가 다리 위에서 노을 봤습니다. 겨울 오기 전에 많이 걸어둘래요.', array[E'리버밸리', E'산책', E'에드먼튼'], '2026-09-10 18:18:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000097'::uuid, '10000000-0000-0000-0000-000000000102'::uuid, 'edmonton', 'life', E'화이트 애비뉴 주말 나들이', E'카페랑 작은 서점이 많아서 하루가 금방 갔어요. 토요일엔 파머스마켓도 열려서 구경하기 좋아요. 에드먼튼 신입인데 여기가 제일 마음에 들어요.', array[E'화이트애비뉴', E'주말', E'카페'], '2026-09-14 13:28:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000098'::uuid, '10000000-0000-0000-0000-000000000118'::uuid, 'edmonton', 'life', E'에드먼튼 겨울 영하 30도 진짜인가요', E'올해 첫 겨울인데 영하 30도가 흔하다는 말에 겁이 나요. 차 시동, 옷차림, 집 관리 뭐부터 준비해야 할지 조언 부탁드려요.', array[E'첫겨울', E'방한', E'에드먼튼'], '2026-09-13 16:53:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000099'::uuid, '10000000-0000-0000-0000-000000000123'::uuid, 'edmonton', 'life', E'K데이즈 다녀오신 분 있나요', E'내년 여름에 꼭 가보고 싶어서 미리 물어봐요. 놀이기구 위주인지 공연 위주인지, 하루면 충분한지 궁금해요.', array[E'K데이즈', E'축제', E'여름'], '2026-09-12 14:37:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000100'::uuid, '10000000-0000-0000-0000-000000000098'::uuid, 'edmonton', 'food', E'에드먼튼 한식당 어디 가세요', E'밀우즈 쪽에 한식당이 몇 개 있다고 들었는데 제대로 된 김치찌개 먹을 수 있는 곳 추천해주세요.', array[E'한식', E'밀우즈', E'맛집'], '2026-09-01 19:49:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000101'::uuid, '10000000-0000-0000-0000-000000000105'::uuid, 'edmonton', 'food', E'다운타운 근처 브런치 맛집 공유', E'일요일에 늦게 일어나서 브런치 먹으러 가는데 항상 같은 곳만 가요. 다운타운이나 올드 스트라스코나 쪽 새로운 곳 알려주세요.', array[E'브런치', E'다운타운', E'일요일'], '2026-09-07 18:29:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000102'::uuid, '10000000-0000-0000-0000-000000000113'::uuid, 'edmonton', 'food', E'웨스트 에드먼튼 몰 푸드코트 추천 메뉴', E'쇼핑하다 배고플 때 뭐 먹으면 좋을지 항상 고민이에요. 여기 가면 꼭 먹는 메뉴 있으신 분?', array[E'웨스트에드먼튼몰', E'푸드코트', E'쇼핑'], '2026-09-12 22:24:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000103'::uuid, '10000000-0000-0000-0000-000000000120'::uuid, 'edmonton', 'settlement', E'알버타 헬스케어 카드 신청 후기', E'레지스트리 가서 신청했는데 서류만 갖춰가면 20분이면 끝나요. 여권, 거주 증명, 체류 자격 이렇게 세 가지였습니다. 카드는 2주 뒤 우편으로 왔어요.', array[E'AHCIP', E'헬스케어', E'정착'], '2026-09-10 08:24:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000104'::uuid, '10000000-0000-0000-0000-000000000117'::uuid, 'edmonton', 'settlement', E'알버타 운전면허 교환 절차', E'한국 면허 교환하려면 레지스트리 예약이 필요한지 궁금해요. 번역 공증은 어디서 받으셨는지도 알려주시면 감사해요.', array[E'운전면허', E'레지스트리', E'정착'], '2026-09-04 21:24:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000105'::uuid, '10000000-0000-0000-0000-000000000111'::uuid, 'edmonton', 'settlement', E'에드먼튼 한인 커뮤니티 어디서 정보 얻으세요', E'밴쿠버나 토론토보다 한인이 적어서 정보 찾기가 어렵네요. 교회나 한인회 말고 소소하게 정보 나누는 곳이 있으면 알려주세요.', array[E'한인', E'정보공유', E'에드먼튼'], '2026-09-01 09:23:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000106'::uuid, '10000000-0000-0000-0000-000000000107'::uuid, 'edmonton', 'travel', E'재스퍼 당일치기 vs 1박', E'에드먼튼에서 재스퍼까지 네 시간 정도라던데 당일치기 하시는 분 계신가요? 1박이 맞을 것 같긴 한데 숙소가 비싸서 고민이에요.', array[E'재스퍼', E'로키', E'여행'], '2026-09-12 12:05:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000107'::uuid, '10000000-0000-0000-0000-000000000104'::uuid, 'edmonton', 'travel', E'엘크 아일랜드에서 바이슨 봤어요', E'시내에서 40분 거리인데 야생 바이슨을 길 옆에서 봤어요. 해 질 때 가면 동물이 더 잘 보인다고 하네요. 별 보기에도 좋대요.', array[E'엘크아일랜드', E'바이슨', E'주말'], '2026-09-14 16:09:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000108'::uuid, '10000000-0000-0000-0000-000000000125'::uuid, 'edmonton', 'shopping', E'에드먼튼에서 한국 식재료 사는 곳', E'한국 마트가 몇 군데 있는지, 김치나 냉동식품 종류가 어느 정도 있는지 궁금해요. 밴쿠버에서 왔는데 선택지가 적어서 적응 중이에요.', array[E'한국마트', E'식재료', E'장보기'], '2026-09-07 13:14:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000109'::uuid, '10000000-0000-0000-0000-000000000110'::uuid, 'edmonton', 'shopping', E'겨울 부츠 어디서 사셨어요', E'영하 30도 견디는 부츠가 필요하다는데 브랜드가 너무 많아요. 실제로 겨울 나보신 분들 추천 부탁드려요.', array[E'겨울부츠', E'방한', E'쇼핑'], '2026-09-01 14:20:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000110'::uuid, '10000000-0000-0000-0000-000000000114'::uuid, 'edmonton', 'transport', E'에드먼튼 LRT 출퇴근 어때요', E'클레어뷰에서 다운타운까지 LRT로 출근 생각 중이에요. 배차 간격이랑 겨울철 지연은 어떤지 경험 공유해주세요.', array[E'LRT', E'출퇴근', E'대중교통'], '2026-09-12 10:42:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000111'::uuid, '10000000-0000-0000-0000-000000000100'::uuid, 'edmonton', 'transport', E'겨울 타이어 언제 갈아야 하나요', E'첫 겨울이라 감이 없어요. 10월 중순이면 늦지 않은지, 올시즌 타이어로 버티는 분도 있는지 궁금해요.', array[E'겨울타이어', E'운전', E'첫겨울'], '2026-09-02 17:39:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000112'::uuid, '10000000-0000-0000-0000-000000000119'::uuid, 'edmonton', 'housing', E'에드먼튼 렌트 시세, 밴쿠버랑 비교하면', E'2베드가 밴쿠버 1베드 값이라는 말이 진짜였어요. 다운타운 근처 2베드 계약했는데 주차까지 포함이었습니다. 동네별 시세 공유해요.', array[E'렌트', E'2베드', E'에드먼튼'], '2026-09-13 19:26:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000113'::uuid, '10000000-0000-0000-0000-000000000122'::uuid, 'edmonton', 'housing', E'겨울 난방비 얼마나 나오세요', E'첫 겨울 앞두고 가스비가 걱정이에요. 2베드 아파트 기준으로 한 달 난방비 어느 정도 나오는지 알려주시면 예산 잡는 데 도움이 될 것 같아요.', array[E'난방비', E'겨울', E'주거'], '2026-09-10 17:51:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000114'::uuid, '10000000-0000-0000-0000-000000000106'::uuid, 'edmonton', 'education', E'알버타 대학 도서관 외부인 이용 가능한가요', E'공부할 곳을 찾다가 U of A 도서관이 좋다고 들었어요. 학생이 아니어도 들어갈 수 있는지, 자리 잡기 어렵지 않은지 궁금해요.', array[E'UofA', E'도서관', E'공부'], '2026-09-02 21:42:00-07'::timestamptz),
  ('20000000-0000-0000-0000-000000000115'::uuid, '10000000-0000-0000-0000-000000000099'::uuid, 'edmonton', 'education', E'아이 스케이트 수업 어디서 시키세요', E'에드먼튼 오면 스케이트는 필수라던데 초등 저학년 아이 수업 등록할 만한 곳 추천해주세요. 시에서 운영하는 프로그램이 있는지도요.', array[E'스케이트', E'자녀교육', E'겨울'], '2026-09-09 18:08:00-07'::timestamptz)
) as seed(id, author_id, city_id, tag_slug, title, body, hashtags, created_at)
join public.tags tag on tag.slug = seed.tag_slug
join public.profiles author on author.id = seed.author_id and author.account_status = 'active'
on conflict (id) do nothing;

-- posts_set_day forces today's date on insert; align with the backdated created_at like older seeds.
update public.posts set posted_on = (created_at at time zone 'America/Edmonton')::date, updated_at = created_at
where id::text like '20000000-0000-0000-0000-%' and substring(id::text from 25)::int between 56 and 115;

-- Random verification badge for synthetic seed profiles only (weighted 1:2:3 = 50:35:15).
update public.profiles profile
set verification_level = case when r < 0.50 then 1 when r < 0.85 then 2 else 3 end
from (select id, random() as r from public.profiles) picked
join auth.users account on account.id = picked.id and account.email like '%@seed.gling.invalid'
where profile.id = picked.id;
